-- 2221 🏋️ Exercises from the book "del-bosque-emery-benitez-luis-enrique-practices-and-training-sessions" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'del-bosque-emery-benitez-luis-enrique-practices-and-training-sessions');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Square in square short-long support passing', 'passing_unopposed', 'unopposed', 'in_possession', 19, 19, 'Real Madrid Passing Drills: Practice 1', 'Del Bosque (Real Madrid)', 'Passing, receiving and support movement to keep the ball moving and create space.', 'A 5 yd square marked inside a 15 yd square, players on the corners of both squares plus extras at the outer corners; 2 balls start at opposite outer corners A and C.', 'Both balls move round the pattern at once mixing short inside passes and long outside passes; each player checks away before receiving and then follows to the next position.', NULL, 'Use 4 balls and/or a 1-touch limit.', 'Pass ahead of the runner and time the support run (not early); keep ball and players moving; receive half-turned with head up.', NULL, 12, 16, '5 yd square inside a 15 yd square', 13.7, 13.7, NULL, false, false, false, NULL, 10),
  ('Square in square diagonal combination passing', 'passing_unopposed', 'unopposed', 'in_possession', 20, 20, 'Real Madrid Passing Drills: Practice 2', 'Del Bosque (Real Madrid)', 'Short and long combinations using diagonal passes.', 'Same nested 5 yd / 15 yd squares; 4 players inside, 4 on the outside and 4 extras waiting at the outer corners; one ball.', 'Ball travels through a set sequence of short lay-offs from the inner players and long diagonal passes across the square; players check away to receive then rotate to the next spot.', NULL, 'Run 2 balls at once from corners A and C.', 'Weight the pass so the receiver runs onto it; accuracy keeps the tempo high.', '12 players', 12, 12, '5 yd square inside a 15 yd square', 13.7, 13.7, NULL, false, false, false, NULL, 20),
  ('9v9 plus 2 jokers fast circulation', 'possession', 'overload', 'in_possession', 22, 22, 'Session 1: Practice 1', 'Del Bosque (Real Madrid)', 'Quick ball circulation and support play under high intensity.', '40 x 50 yd area, two teams of 9 and 2 neutral jokers who join the side with the ball.', 'Team in possession tries to string 10 passes for a point; defenders win it back and look to do the same.', 'Max 2 touches, 1 touch encouraged; 10 passes = 1 point.', NULL, 'Spread for width and depth; build triangles and open up to receive; driven passes on the ground and show where you want it.', '9v9+2', 20, 20, '40 x 50 yards', 45.7, 36.6, 18.0, false, false, false, NULL, 30),
  ('6v6 plus 2 rotating outside players', 'possession', 'overload', 'in_possession', 23, 23, 'Session 1: Practice 2', 'Del Bosque (Real Madrid)', 'Keeping possession and supporting after a pass into an outside player.', '40 x 50 yd area, each team has 6 inside and 2 outside players, one at each end.', 'Team keeps the ball and finds one of its end players; that player steps in and the passer swaps out to replace him, scoring a point if done without losing the ball.', 'Max 2 touches, 1 touch when possible; each successful position swap = 1 point. 12 minutes non-stop at 140-150 bpm.', NULL, 'After passing to an outside player, create good support angles for the return.', '6(+2)v6(+2)', 16, 16, '40 x 50 yards', 45.7, 36.6, 12.0, false, false, false, NULL, 40),
  ('Three-zone 7v7 play forward quickly', 'small_sided_game', 'opposed', 'in_possession', 24, 24, 'Session 1: Practice 3', 'Del Bosque (Real Madrid)', 'Building up and moving the ball forward fast through midfield into the attacking zone.', 'Pitch split into 3 zones with full goals and GKs: 2v1 in the low zone (plus GK), 3v3 in the middle, 1v2 in the high zone.', 'One middle player may drop into the low zone to make 3v1 in build-up; the middle zone is only a passage to feed the high zone quickly, then one middle player joins the attack for 2v2. Restart with the other team after a goal or ball out.', '2 touches in low/high zones, 1 touch in the middle zone; 12 minutes at 150-160 bpm.', NULL, 'Open body shape to receive and play a driven one-touch pass on the ground into the high zone.', '7v7 plus GKs', 16, 16, NULL, NULL, NULL, 12.0, true, true, true, NULL, 50),
  ('Three-team 6+6 v 6 two-ball possession', 'possession', 'overload', 'in_possession', 26, 26, 'Session 2: Practice 1', 'Del Bosque (Real Madrid)', 'Keeping possession with a numerical advantage and quick one-touch passing.', 'Large area with 3 teams of 6 and 2 balls in play at once.', 'Two teams combine (12v6) to keep both balls using the full area; the 6 defenders try to win a ball and, if they do, the team that lost it becomes the defenders.', '12 minutes continuous.', NULL, 'Width and depth, triangles, driven ground passes, one touch where possible otherwise a clean receive and aware pass.', '6+6v6', 18, 18, NULL, NULL, NULL, 12.0, false, false, false, NULL, 60),
  ('Position-specific agility stations with finishing', 'conditioning', 'passive', 'in_possession', 27, 27, 'Session 2: Practice 2', 'Del Bosque (Real Madrid)', 'Coordination, speed and agility by position combined with passing, a 2v1 attack and finishing.', '5 stations (A-E) by position around a goal: hurdles, ladders, poles and hoops; central players, wide players, attackers and defenders each have their own station.', 'A: sprint and hurdles, header or volley, ladder, pass. B: poles slalom, hurdles, sprint. C: pass to a second player who feeds D, then run into the box to finish. D: hurdle, check away, receive and cross for C. E: hoops, poles, then defend the goal. C, D and E work together to make a 2v1 attack.', 'A and B work continuously with rest between sets; B and D swap halfway.', NULL, NULL, '5 stations by position', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Two-zone 11v11 play forward and finish', 'conditioned_game', 'overload', 'in_possession', 28, 28, 'Session 2: Practice 3', 'Del Bosque (Real Madrid)', 'Moving the ball quickly from your own half into the attacking half and finishing.', 'Area split into 2 halves, 11v11 with GKs; 4v4 in each half plus 2 wide full backs per team outside, giving a 4(+2)v4 in build-up.', 'GK starts, the team builds up using the overload, finds a wide player who plays into the attacking half; then one player advances to make 5v4 and finish quickly. Restart with the other team when the ball is dead.', '20 minutes continuous, then 4 minutes stretching.', NULL, 'Move the ball forward fast; attackers check away from markers to open passing lanes.', '11v11', 22, 22, NULL, NULL, NULL, 20.0, true, true, true, NULL, 80),
  ('6v6 with two back-to-back central goals', 'small_sided_game', 'opposed', 'in_possession', 30, 30, 'Session 3: Practice 1', 'Del Bosque (Real Madrid)', 'Creating space to shoot quickly and pressing as a unit to protect goals.', 'Area between the two penalty boxes, two teams of 6 and 2 GKs in goals facing opposite ways either side of the centre circle.', 'Starting from a GK, the team in possession uses the whole area to make space and score in either goal; defenders win the ball and attack either goal.', '20 minutes with 2 minutes rest at halfway.', NULL, 'Shoot as soon as there is a yard of space; defenders press together, block lanes to goal and mark the next receivers.', '6v6 + 2 GKs', 14, 14, 'Between the two penalty areas', NULL, NULL, 20.0, true, true, false, NULL, 90),
  ('1v1, 2v2 duels and 3v3 game', 'one_v_one', 'opposed', 'in_possession', 31, 31, 'Session 3: Practice 2', 'Del Bosque (Real Madrid)', 'Winning individual and small-group duels.', '3 groups: A a 1v1 with small cone goals at each end and 2 outside helpers; B a 2v2 to mini goals with an outside helper; C a 3v3 with 2 full goals and GKs.', 'A: score by dribbling through the opponent''s cone goal, using the 1-touch outside players. B: 2v2 to mini goals using the 1-touch outside player. C: normal 3v3 game.', 'Outside players are limited to 1 touch.', NULL, 'Finish with 4 minutes of stretching.', '1v1+2, 2v2+1, 3v3+GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Three-zone game with touch limits', 'conditioned_game', 'overload', 'in_possession', 32, 32, 'Session 3: Practice 3 (Del Bosque''s favourite)', 'Del Bosque (Real Madrid)', 'Playing forward quickly and building automatisms for a fast game.', 'Three zones with full goals: 4(+GK)v3 in the low zone, 3v3 in the middle, 3v4 in the high zone.', 'Whites use their 5v3 with the GK to get the ball into the middle quickly, then move it on into the final zone where one middle player joins for 3+1v4. Restart with the other team after a goal or ball out.', '1-2 touches in the low zone, 2 touches in the middle, free touches in the high zone.', NULL, 'Be creative in attack; open body to receive and play a weighted forward pass on the ground.', '11v11 incl. GKs', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Y-shape one-two, receive and shoot', 'combination', 'unopposed', 'in_possession', 34, 34, 'Session 4: Practice 1', 'Del Bosque (Real Madrid)', 'One-touch combination play at tempo ending in a shot.', 'Players set in a Y shape from the centre circle towards goal with mannequins as markers, GK in goal.', 'A plays a one-two with B then passes first time out to C, who checks wide and comes inside to receive and shoot. Rotate A to B to C to start; then repeat on the left side.', 'All passes 1 touch; 20 minutes with 6-8 players, 1-2 minutes rest halfway.', NULL, 'Weighted passes in front of the receiver; high tempo; C''s first touch out in front towards goal ready to shoot.', '6-8 players + GK', 6, 8, NULL, NULL, NULL, 20.0, true, true, true, NULL, 120),
  ('Y-shape combination with lay-off support', 'combination', 'unopposed', 'in_possession', 35, 35, 'Session 4: Practice 2', 'Del Bosque (Real Madrid)', 'Attacking combination with a supporting run and finish.', 'Same Y shape with mannequins and GK, plus a fourth player D on the opposite side.', 'After A''s pass to C, B spins and moves forward to take a lay-off from C, then passes to D who comes inside to receive and shoot. Rotate A, B, C, D and repeat on the other side with C shooting.', '20 minutes with 6-8 players, 1-2 minutes rest halfway.', 'Reduce time between touch and pass, progressing to 1 touch.', 'Receive on one foot and pass with the other; first touch out in front of the body.', '6-8 players + GK', 6, 8, NULL, NULL, NULL, 20.0, true, true, true, NULL, 130),
  ('Playing out from back: patterns or direct', 'combination', 'unopposed', 'in_possession', 36, 36, 'Session 4: Practice 3', 'Del Bosque (Real Madrid)', 'Rehearsed patterns to move the ball from back to front, mixing short combinations and a direct forward pass.', 'Full team in shape on a full pitch from the GK, opposite goal at the far end.', 'Players run set patterns chosen by the coach from the GK through midfield; defenders may instead skip midfield and play straight to the forwards (e.g. a full back''s long pass).', '20 minutes; patterns varied to suit the game situation and upcoming opponent.', 'Let players invent their own patterns; then add passive defenders and then active ones.', NULL, '11 players', 11, 11, 'Full pitch', NULL, NULL, 20.0, true, true, true, NULL, 140),
  ('5v5 central zone then fast attacks', 'conditioned_game', 'opposed', 'in_possession', 37, 37, 'Session 4: Practice 4', 'Del Bosque (Real Madrid)', 'Playing through the centre and launching quick attacks to the striker.', 'Both teams in 4-3-3: a central area holds 3 midfielders and 2 wingers each (5v5); outside it each side has GK, back four and one forward.', 'GK or a defender passes into the central area; the team keeps it in the 5v5 and finds its forward. Once the forward receives, the wingers (and overlapping full backs) leave the area to support and the attack goes at the back four. Winning the ball in the centre means a fast break the other way.', 'Must pass to a teammate in the centre, and to the striker before advancing; restart from the opposition GK after a goal or ball out.', NULL, 'Forward keeps moving to offer a passing line; wingers make direct forward runs to support quickly.', '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Four colours reaction receive and finish', 'technical', 'unopposed', 'in_possession', 55, 55, 'Technical Practices: Practice 1', 'Emery (PSG)', 'Awareness, vision, body shape and technique of receiving and passing.', '10 yd square with one central player, 4 coloured mannequins inside and 4 small goals outside, each with a feeder of that colour.', 'Coach calls three colours in turn: the player touches the first mannequin, receives from the second colour''s feeder and passes into the third colour''s goal with the right body shape.', 'Repeat until the central player has received 4 balls.', NULL, NULL, '1 central player + 4 feeders', 5, 5, '10 x 10 yards', 9.1, 9.1, NULL, true, false, false, NULL, 160),
  ('Open up and play forward circuit', 'passing_unopposed', 'passive', 'in_possession', 56, 56, 'Technical Practices: Practice 2', 'Emery (Arsenal)', 'Checking away, opening up on the half-turn and playing forward, then switching play to goal.', 'Circuit round the centre circle with mannequins as defenders and players A-G; two small goals (blue and red) at the end.', 'Ball goes A to B to C to D to E to F to G, each player following his pass; receivers check off their mannequin and open up. D faces C but turns play towards E; G dribbles round the last mannequin and scores in the goal whose colour the coach shows.', NULL, NULL, 'Receiver may choose either side of the mannequin, so the passer must read the movement.', '8+ players', 8, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 170),
  ('End to end GK to GK possession', 'positional_game', 'overload', 'in_possession', 58, 58, 'Possession Games: Practice 1', 'Emery (Arsenal)', 'Positional and support play to keep the ball and move it from one end to the other.', 'Marked area around halfway with 2 teams of 6, 2 neutral players and a neutral GK at each end.', 'Team in possession uses the neutrals to move the ball from one GK to the other and back again; defenders press together and, on winning it, switch roles and attack the GKs themselves.', NULL, NULL, NULL, '6v6+4 (2 neutrals + 2 GKs)', 16, 16, NULL, NULL, NULL, NULL, false, true, true, NULL, 180),
  ('Four-zone possession, switch after 8-10 passes', 'possession', 'overload', 'in_possession', 59, 59, 'Possession Games 2', 'Emery (Arsenal)', 'Keep the ball with good positioning and support, then switch the point of attack.', 'Square split into 4 equal zones; two teams of 8 plus 5 neutrals who join the side on the ball, spread across the zones.', 'Coach serves into one zone where a 3v3 plus 3 neutrals plays out; the side on the ball strings 8-10 passes, then plays into another zone where players must quickly rebuild the same 3v3+3 picture.', '8-10 passes needed before switching zones; if the defending team wins it, roles swap.', NULL, 'Players in the other zones stay spread and ready to rebuild the numbers in the next zone.', '2 x 8 + 5 neutrals', 21, 21, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 190),
  ('Speed and agility warm-up circuit', 'warm_up', 'unopposed', NULL, 61, 61, 'Warm-Up Circuits 1', 'Emery (Arsenal)', 'Warm up with coordination, speed and agility work linked to passing.', 'Rectangular circuit with a different speed/coordination station at each corner (mini hurdles, rings, slalom poles); players start in the middle.', 'Each player plays one pass in the centre, then moves left and works round the circuit stations; at the pole corner he slaloms through and plays a pass before carrying on.', NULL, 'Pass variations: two touch keeping it off the ground, headers, dribbling.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 200),
  ('Mannequin finishing warm-up with colour call', 'warm_up', 'unopposed', NULL, 62, 62, 'Warm-Up Circuits 2', 'Emery (Arsenal)', 'Technical finishing warm-up with an awareness and reaction element.', 'Two areas, each with two mini goals and mannequins; players rotate round the two areas in a circuit.', 'Area 1: coach lobs the ball over two mannequins, player controls with one touch and finishes into either mini goal with the second. Area 2: player side-steps through mannequins, coach shows or shouts a colour and the player must score in that colour''s mini goal.', 'Area 1: control then finish, two touches.', 'Allow 1 or 2 touches; coach serves along the floor or throws up for a header.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 210),
  ('Overlap, cut-back and finish plus rebound', 'combination', 'unopposed', 'in_possession', 64, 64, 'Attacking Combination Play 1', 'Emery (Arsenal)', 'Quick combination play with timed runs, weighted passes and finishing.', 'Groups of 3 start on red cones around the centre circle with mannequins and a pole leading to a goal with a GK.', 'A passes to B who comes round a mannequin to receive while A runs forward; B plays across for C to run onto and B attacks the far post; C dribbles at a mannequin while A overlaps round the pole; C feeds A who cuts it back for C to shoot; coach then serves a second ball to B to finish.', NULL, NULL, NULL, 'Groups of 3 + GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Overlap combination and finish plus pressured rebound', 'combination', 'passive', 'in_possession', 65, 65, 'Attacking Combination Play 2', 'Emery (Arsenal)', 'Quick combination play, timing of runs, pass weight and finishing.', 'Groups of 3 in a vertical line with mannequins and a pole in front of the box; goal with GK.', 'A passes to B who drifts left to receive while A loops round to the right; B dribbles then passes across to C coming off his cone in front of a mannequin; C dribbles and feeds A on the overlap round the pole; A shoots; coach serves a second ball to B and puts pressure on his finish.', NULL, NULL, NULL, 'Groups of 3 + GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('One-two, dribble past coach and finish', 'finishing', 'passive', 'in_possession', 67, 67, 'Finishing Practices 1', 'Emery (Arsenal)', 'Dribble to beat a defender, make room for a shot and finish.', 'Mannequins around the edge of the box, rearranged often during the drill; goal with GK; coach acts as passive defender.', 'Player plays a one-two with the coach, dribbles forward, beats a passive defending coach with a 1v1 move and shoots past the GK; next player goes.', NULL, 'Change the start cone (central or left) and where the coach defends.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Back-to-goal receive, one-two and finish', 'finishing', 'passive', 'in_possession', 68, 68, 'Finishing Practices 2', 'Emery (Arsenal)', 'Receive with back to goal, shield, play one touch and turn to finish.', 'Players spread across three positions (A, B, C) at the top of the box; coach with a crash pad behind the receiver; goal with GK.', 'Coach bounces the ball to A who receives with his back to goal under crash-pad pressure, shields and lays off to B; B slips the ball ahead for A to run onto and shoot. Repeat on the other side with C.', NULL, 'Players simply receive, turn and shoot without the one-two.', 'Coach varies the service, from standing still and on the move.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('One-two in behind and finish plus rebound', 'combination', 'unopposed', 'in_possession', 69, 69, 'Finishing Practices 3', 'Emery (Arsenal)', 'Quick combination play and finishing.', 'Pairs start outside the box among mannequins; coach serves from wide; goal with GK.', 'Coach passes to A, A plays across to B, B slides the ball into the box for A who has run round a mannequin; A shoots. Coach then serves a second ball to B for a first-time finish unless he is already following up A''s rebound.', 'B finishes first time.', NULL, NULL, 'Pairs + GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Timed runs into the box with cross plus rebound', 'finishing', 'unopposed', 'in_possession', 70, 70, 'Finishing Practices 4', 'Emery (Arsenal)', 'Opening up the body to receive and finish, and timing runs to attack a cross.', 'Three players (A centrally, B near a pole, C wide) around mannequins and poles at the box; goal with GK.', 'A dribbles while B loops round the pole; A passes into the box and B opens up to receive and shoot. C then dribbles wide and crosses a second ball for A who has run round the mannequins to finish. Repeat on the other side.', NULL, NULL, NULL, '3 + GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('1v1 on the wing, cross and finish plus rebound', 'finishing', 'opposed', 'in_possession', 71, 71, 'Finishing Practices 5', 'Emery (Arsenal)', 'Beat a defender in a 1v1, cross and finish.', 'Attackers start wide outside the box with a yellow defender; two forwards (C and D) start by the mannequins; goal with GK; coach by the post with balls.', 'A plays a one-two with the defender then passes wide to B as the defender steps out to contest; B beats him to make space and crosses for C and D attacking the box; one shoots and the other follows for the rebound, otherwise the coach serves a second ball for a one-touch finish.', 'Second-ball finish is one touch.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Three-team fast attacks and transitions', 'transition', 'opposed', 'to_attack', 73, 73, 'Small Sided Games 1', 'Emery (PSG)', 'Fast combination play to score quickly, plus transitions after winning the ball.', 'Pitch in three zones with a full goal and GK at each end; one team in each zone, coach with balls by the middle zone.', 'The middle team attacks one end team and tries to score quickly; if they score they get a new ball from the coach and attack the other end, and keep going while they score. If they miss, the defending team takes a new ball into the middle and attacks the far end. If the defenders win the ball they pass to the coach and attack the other end at once, while the team that lost it moves to that end to defend next.', NULL, NULL, NULL, '3 teams + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('7v7 with GK end zones and four mini goals', 'small_sided_game', 'opposed', 'in_possession', 74, 74, 'Small Sided Games 2', 'Emery (Arsenal)', 'Build-up, ball circulation, combination play and finishing.', '7v7 in an area with an end zone at each end containing two mini goals defended by one GK.', 'Coach passes to one team who play through the two middle zones and try to get the ball into the end zone, by dribble or pass, then score in a mini goal; once it enters, all players may follow into the end zone. If the defenders win it, roles reverse; after a goal or out of play the coach feeds the other team.', 'Players may only enter the end zone once the ball has been played or dribbled in.', NULL, NULL, '7v7 + 2 GKs', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Finishing game with outside end players', 'small_sided_game', 'overload', 'in_possession', 75, 75, 'Small Sided Games 3', 'Emery (Arsenal)', 'Create space and get lots of shots and finishes.', 'Normal game between two goals with GKs; each team has 5 inside and 4 extra players outside the area in their attacking half.', 'Play starts from either GK; teams look to find their outside players, who return the ball or cross it for the inside players to shoot.', NULL, NULL, NULL, '5v5 + 4 outside players each + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Diamond passing drill with dribble round mannequin', 'passing_unopposed', 'unopposed', 'in_possession', 84, 84, 'Napoli Session 1: Practice 1', 'Benitez (Napoli)', 'Passing and receiving with check-away and opening up, plus dribbling.', 'Cones in a diamond with a mannequin in the middle and two red cones on one side; players at each point.', '1 passes to 2 and follows, 2 passes to 3 and follows; 3 dribbles through the red cones and round the mannequin, passes to 4 and goes to the start. Continue the other way starting with 4 to 5.', NULL, NULL, 'Check away from the cone before every receive.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, NULL, 320),
  ('Diamond passing with quick one-two combinations', 'passing_unopposed', 'unopposed', 'in_possession', 85, 85, 'Napoli Session 1: Practice 2', 'Benitez (Napoli)', 'Quick one-two combinations and passing/receiving in a diamond.', 'Same diamond as the previous drill with a central mannequin and red cones.', '1 plays a one-two with 2 and passes to 3, then takes 2''s spot; 3 plays a one-two with 2 running through the cones for the return, 2 takes 3''s spot; 3 dribbles round the mannequin, passes to 4 and goes to the start. Then the other side from 4 to 5.', NULL, NULL, 'Keep checking away before receiving.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, NULL, 330),
  ('Diamond passing with run in behind and dribble', 'passing_unopposed', 'unopposed', 'in_possession', 86, 86, 'Napoli Session 1: Practice 3', 'Benitez (Napoli)', 'Receiving on the move and dribbling at speed.', 'Same diamond with a central mannequin.', '1 passes to 2 and follows; 2 plays in front of the mannequin and moves on; 3 times a sprint forward to take 2''s pass on the run in behind, then dribbles fast to the start. Continue the other way from 4 to 5.', NULL, NULL, 'Time the run so the pass is met at speed.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, NULL, 340),
  ('Four-zone rondo, switch within 4 passes', 'possession', 'overload', 'in_possession', 87, 87, 'Napoli Session 1: Practice 4', 'Benitez (Napoli)', 'Quick passing and fast circulation to switch the point of attack.', 'Square split into 4 zones; players move freely between zones, coach serves from outside.', 'Coach passes to one team who keep the ball across the four zones; only 3 defenders may be in the zone with the ball. If the defenders win it they become the team keeping the ball.', 'Max 4 passes in a zone before the ball must be switched to another zone; max 3 defenders in the active zone.', NULL, NULL, NULL, NULL, NULL, '20 x 20 yards', 18.3, 18.3, 10.0, false, false, false, NULL, 350),
  ('9v9 build-up game with passing gates', 'conditioned_game', 'opposed', 'in_possession', 88, 88, 'Napoli Session 1: Practice 5', 'Benitez (Napoli)', 'Team shape, build-up play, accurate passing and finishing attacks.', 'Normal 9v9 plus GKs on a large pitch with 4 small cone gates placed in the field.', 'Blue team builds up from the GK in their set formation and shape aiming to play forward and score; they also earn a point by passing through any cone gate.', 'Goal = 1 point; pass through a cone gate = 1 point.', NULL, 'Intelligent movement to open passing lanes; firm passes along the ground.', '9v9 + 2 GKs', 20, 20, NULL, NULL, NULL, 20.0, true, true, true, NULL, 360),
  ('Open up, one-two and long pass sequence', 'passing_unopposed', 'unopposed', 'in_possession', 90, 90, 'Napoli Session 2: Practice 1', 'Benitez (Napoli)', 'Passing and receiving technique.', 'Rectangle with mannequins at A, B, C, D and players at each point plus A2, B2, C2, D2; at least 6 players; two balls start at A and C.', 'A one-twos with B and plays long to C2 while C one-twos with D and plays long to A2; C2 and A2 open up and take a first touch behind their mannequin, then restart with one-twos to B2 and D2. Players rotate A to B to C to D.', NULL, NULL, 'Check away before each receive.', '6+', 6, NULL, '18-20 x 25 yards', 22.9, 17.4, NULL, false, false, false, NULL, 370),
  ('One-touch pass and move combination', 'passing_unopposed', 'unopposed', 'in_possession', 91, 91, 'Napoli Session 2: Practice 2', 'Benitez (Napoli)', 'One-touch combination play with runs behind mannequins.', 'Same rectangle and mannequins as the previous sequence; two balls start at A and C.', 'A one-twos with B and passes to C2, C one-twos with D and passes to A2; C2 one-twos with B and runs behind the mannequin for the return, A2 does the same with D; then they restart with B2 and D2. Players rotate A to B to C to D.', NULL, NULL, 'Check away before each receive.', '6+', 6, NULL, '18-20 x 25 yards', 22.9, 17.4, NULL, false, false, false, NULL, 380),
  ('7v3 possession, switch and support', 'rondo', 'overload', 'in_possession', 92, 92, 'Napoli Session 2: Practice 3', 'Benitez (Napoli)', 'Passing, receiving, interceptions and transitions.', 'Rectangle with 6 blues on the outside and 1 inside, 3 yellows inside; coach serves from outside.', 'Coach passes to the blues who keep the ball, switching from end to end and quickly supporting the man on the ball; the 3 yellows press as a group. A yellow who intercepts swaps with the blue who lost it.', 'Max 2 touches, mostly 1.', NULL, NULL, '7v3', 10, 10, '10 x 20 yards', 18.3, 9.1, NULL, false, false, false, NULL, 390),
  ('Pass through the lines to end-zone target', 'positional_game', 'opposed', 'in_possession', 93, 93, 'Napoli Session 2: Practice 4', 'Benitez (Napoli)', 'Pass through lines with good angles and accuracy; defenders stay compact and intercept.', 'Area with two 5-yard end zones; each team has 4 in the middle and 1 player in an end zone.', 'Coach feeds the blues who move it among themselves and choose the moment to pass to their end-zone teammate (1 point); yellows shift across together to block and intercept. After each attempt the coach serves to the other team going the other way.', 'Successful pass to end-zone player = 1 point.', NULL, 'End-zone player keeps moving to offer a line; defenders keep short distances.', '4v4 + 2 end players', 10, 10, '18 x 25 yards', 22.9, 16.5, NULL, false, false, true, NULL, 400),
  ('Three-team possession with one-touch rebounders', 'possession', 'overload', 'in_possession', 94, 94, 'Napoli Session 2: Practice 5', 'Benitez (Napoli)', 'Passing, receiving, interceptions and pressing.', '7v7 inside an area with a third team placed around the outside, playing with the team on the ball.', 'Coach passes to one inside team, who keep it with help from the outside players; the other inside team presses to win it. Keep rotating team roles.', 'Outside players 1 touch; a pass to an outside player who returns it one touch to the same player = 1 point.', NULL, NULL, '7v7+7', 21, 21, NULL, NULL, NULL, NULL, false, false, false, NULL, 410),
  ('5v3 rondo in a tight space', 'rondo', 'overload', 'in_possession', 104, 104, 'Roma Session: Practice 1', 'Luis Enrique (Roma)', 'Keep the ball in tight spaces.', 'Rectangle with 4 reds on the outside (one per side) and 1 inside, 3 yellows inside; coach serves.', 'Coach passes to the reds who keep it against 3 pressing yellows. A yellow who wins it swaps with the outside player who lost it.', NULL, NULL, 'Precise, well-weighted passes; use all the space; quick decisions to find the free man.', '5v3', 8, 8, '15 x 18 yards', 16.5, 13.7, NULL, false, false, false, NULL, 420),
  ('6v6+1 through the lines to mini goals', 'positional_game', 'overload', 'to_attack', 105, 105, 'Roma Session: Practice 2', 'Luis Enrique (Roma)', 'Play through the opposition into the final third; win the ball and transition quickly.', 'Area with end zones, three mini goals on each end line; each team has 2 full backs, 2 wingers, 2 central mids; 1 neutral striker.', 'Reds start with a full back and build up using the neutral striker to play through and score in a mini goal at the far end. If yellows win it they counter fast to score at the other end while reds transition back to defend.', 'Neutral 1 touch, may not enter end zones or score. Defenders: left back guards the left goal, right back the right goal, central mids the middle goal.', NULL, NULL, '6v6+1', 13, 13, NULL, NULL, NULL, NULL, true, false, true, NULL, 430),
  ('8v5 attacking patterns with counter to mini goals', 'phase_of_play', 'overload', 'in_possession', 106, 106, 'Roma Session: Practice 3', 'Luis Enrique (Roma)', 'Attacking patterns and effective finishing; defending compactly and recovering the ball.', 'Half pitch with a full goal and GK; 3 mini goals on the halfway line. Reds: 2 full backs, 3 central mids, 2 wingers, 1 forward. Yellows: 2 centre backs, 2 full backs, 1 holding mid.', 'Reds start from the holding mid and use rehearsed combinations and their numbers to score, e.g. using high full backs to exploit width. If yellows win it they counter by passing into a halfway mini goal.', 'Mini goals stand for 2 wingers and a forward to receive the counter pass.', NULL, NULL, '8v5 + GK', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Continuous 3v2 duels to two goals', 'one_v_one', 'overload', 'in_possession', 107, 107, 'Roma Session: Practice 4', 'Luis Enrique (Roma)', 'Exploit a numerical advantage and finish; press to win the ball.', 'Area twice the size of the penalty box with a full goal and GK at each end; waiting players of each team by the goals.', 'From the GK, 3 reds attack 2 yellows. If reds score they stay in and attack the other goal against 2 fresh yellows. If yellows win it, a third yellow joins and they attack 3v2 against 2 new reds while the 3 reds who lost it leave.', NULL, NULL, NULL, '3v2 + 2 GKs, rotating', NULL, NULL, '2 x penalty area', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Three-team zonal game with wide jokers', 'transition', 'overload', 'in_possession', 108, 108, 'Roma Session: Practice 5', 'Luis Enrique (Roma)', 'Play in tight spaces covering build-up, final-third attacks, finishing and transitions at once.', 'Pitch in 3 zones with a goal and GK at each end; reds in the middle, yellows and whites in the end zones; 2 blue jokers in the wide side zones.', 'Reds start from their GK 5v5 against yellows in zone 1 and dribble or pass into zone 2, then attack whites in zone 3 with the two jokers for a 7v5. If yellows win it in zone 1 they take over and attack through to zone 3 while reds stay; if whites win in zone 3 they attack back the other way.', NULL, NULL, NULL, '3 teams of 5 + 2 jokers + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 460),
  ('4v4+3 positional rondo with counter-press', 'rondo', 'overload', 'to_defend', 110, 110, 'Barcelona Training Practices 1', 'Luis Enrique (Barcelona)', 'Keep the ball and, on losing it, press straight away to win it back.', '15-yard square; 4 blues on the sides (2 per side), 4 yellows inside; 3 red jokers, one at each end and one in the middle.', 'Coach serves to blues who keep the ball with the jokers against pressing yellows; ball out = new ball to blues. When yellows win it the roles swap: blues close in at once to press the ball carrier while yellows move to the outside to keep it.', NULL, NULL, 'Instant reaction on losing the ball.', '4v4+3', 11, 11, '15 x 15 yards', 13.7, 13.7, NULL, false, false, false, NULL, 470),
  ('Three-team rondo switching via a joker', 'rondo', 'overload', 'to_defend', 111, 111, 'Barcelona Training Practices 2', 'Luis Enrique (Barcelona)', 'Make angles to keep the ball and switch play; transition to defence after losing it; collective pressing.', 'Rectangle split in half; 3 teams of 3 and 1 joker on the halfway line; blues and yellows in one half, reds in the other.', 'Blues keep the ball against yellows aiming to find the joker, who sets it back to a blue, who then plays to the reds in the other half. Yellows then move across to defend against the reds, who try to switch back via the joker. If defenders win it they play to the far half and swap roles with the team that lost it.', 'Team on the ball 2-3 touches.', NULL, NULL, '3 x 3 + 1 joker', 10, 10, '12 x 36 yards', 32.9, 11.0, NULL, false, false, false, NULL, 480),
  ('5v5+1 fast attacks game', 'small_sided_game', 'overload', 'in_possession', 112, 112, 'Barcelona Training Practices 3', 'Luis Enrique (Barcelona)', 'Fast attacks with support play and finishing.', 'Two goals with GKs in a shortened area; 5v5 plus 1 joker for the team on the ball.', 'Normal game where the emphasis is to play forward and score quickly; GK picks the best distribution (short, medium or long). Once the ball enters the opposition half, all outfield players push up to support.', 'Out at the sides = throw-in; out at the ends = restart from GK.', NULL, NULL, '5v5+1 + 2 GKs', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Zonal positional attacks to play in behind', 'phase_of_play', 'opposed', 'in_possession', 113, 113, 'Barcelona Training Practices 4', 'Luis Enrique (Barcelona)', 'Positional build-up and attacks to play in behind the back line, with fast transitions both ways.', 'Half pitch in 3 zones plus the penalty area and goal; blues in 4-3-3 against yellows in 4-4-1, each player fixed in his zone (2v1 in zone 1, 5v4 midfield, 3v4 in zone 3).', 'Coach passes to a blue centre back in zone 1; blues use positional attacks to get the ball in behind into the box by dribbling over the line or receiving a pass from any zone. One blue may step from zone 2 to zone 3 to make 3+1 v 4. If yellows win it they counter and try to play in behind at the other end.', 'Yellows must stay in their zones; one blue may advance a zone.', NULL, NULL, '11v10 approx (4-3-3 v 4-4-1)', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 500)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'del-bosque-emery-benitez-luis-enrique-practices-and-training-sessions') b;
INSERT INTO schema_migrations (filename) VALUES ('2221-exercises-book-del-bosque-emery-benitez-luis-enrique-practices-and-training.sql') ON CONFLICT DO NOTHING;
